    }
#ifdef ACCOUNT_ONLY
    Ledger after = ledger;
    if (operation == 0 || strcmp(api->name, "cpp-unordered-map") != 0) {
        require(memcmp(&before, &after, sizeof before) == 0, "nonallocating batch ledger");
    } else {
        require(after.requests - before.requests == count * generation
                && after.releases - before.releases == count * generation
                && after.live == before.live, "C++ churn node allocation ledger");
    }
    if (fault == FAULT_LEDGER_LEAK) (void)wf_cost_allocate(8);
#endif
    uint64_t cleanup = api->finish(storage.bytes);
    if (fault == FAULT_CLEANUP) cleanup ^= 1;
    require(cleanup == expected_cleanup(api->wide, count, seed, generation),
            fault == FAULT_CLEANUP ? "negative cleanup checksum"
            : "independent full-content cleanup oracle");
#ifdef ACCOUNT_ONLY
    if (fault == FAULT_LEDGER_LEAK)
        require(ledger.live == 0 && ledger.requests == ledger.releases, "negative ledger leak");
    if (report)
        printf("%s,%s,%s,%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%s,%" PRIu64
               ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64
               ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64
               ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 "\n",
               api->name, api->capacity_kind, api->wide ? "wide256" : "word8",
               slots, count, geometry >> 32, operation ? "churn" : "replace", generation,
               before.requests, before.releases, before.bytes, before.live, before.peak,
               after.requests - before.requests, after.releases - before.releases,
               after.bytes - before.bytes, after.live,
               ledger.requests, ledger.releases, ledger.bytes, ledger.live, ledger.peak);
#else
    (void)report;
#endif
