}
static void check_all(void) {
    const uint64_t slots[] = {64, 4096};
    const uint64_t seeds[] = {17, 101, UINT64_MAX};
    unsigned cases = 0;
    for (size_t a = 0; a < sizeof apis / sizeof *apis; ++a)
        for (size_t c = 0; c < sizeof slots / sizeof *slots; ++c)
            for (size_t s = 0; s < sizeof seeds / sizeof *seeds; ++s)
                for (uint64_t op = 0; op < 2; ++op) {
                    checked(&apis[a], slots[c], seeds[s], op, FAULT_NONE, false); ++cases;
                }
