}
static void negative(const char *kind) {
    Fault fault;
    if (strcmp(kind, "wrong-batch-checksum") == 0) fault = FAULT_BATCH;
    else if (strcmp(kind, "stale-generation") == 0) fault = FAULT_GENERATION;
    else if (strcmp(kind, "corrupt-last-word") == 0) fault = FAULT_LAST_WORD;
    else if (strcmp(kind, "cleanup") == 0) fault = FAULT_CLEANUP;
#ifdef ACCOUNT_ONLY
    else if (strcmp(kind, "ledger-leak") == 0) fault = FAULT_LEDGER_LEAK;
    else if (strcmp(kind, "filled-allocation") == 0) fault = FAULT_FILLED_ALLOCATION;
#endif
    else { require(false, "unknown or unavailable negative control"); return; }
    checked(&apis[4], 64, 101, 0, fault, false);
    /* An uncaught fault returns 0: no always-failing fallback can masquerade
     * as the particular guard this control is intended to exercise. */
    puts("mutation: negative control was not rejected");
}
#ifdef ACCOUNT_ONLY
static void account(void) {
    const uint64_t slots[] = {64, 4096};
    puts("variant,capacity_kind,width,slots,population,capacity,operation,rounds,filled_requests,filled_releases,filled_bytes,filled_live,filled_peak,batch_requests,batch_releases,batch_bytes,batch_live,final_requests,final_releases,final_bytes,final_live,final_peak");
    for (size_t a = 0; a < sizeof apis / sizeof *apis; ++a)
        for (size_t c = 0; c < sizeof slots / sizeof *slots; ++c)
            for (uint64_t op = 0; op < 2; ++op)
                checked(&apis[a], slots[c], 101, op, FAULT_NONE, true);
}
#endif
#ifndef ACCOUNT_ONLY
static uint64_t nanoseconds(void) {
    struct timespec instant;
    require(clock_gettime(CLOCK_MONOTONIC, &instant) == 0, "clock");
    return (uint64_t)instant.tv_sec * UINT64_C(1000000000) + (uint64_t)instant.tv_nsec;
}
static uint64_t parse_work(const char *text) {
    char *end = NULL; unsigned long long work = strtoull(text, &end, 10);
    require(end != text && *end == '\0' && work > 0 && work <= UINT64_C(16777216), "work");
    return (uint64_t)work;
}

static void measure(unsigned cohort, uint64_t work) {
    const uint64_t slots[] = {64, 4096};
    puts("variant,capacity_kind,width,slots,population,capacity,operation,cohort,sample,seed,start_generation,rounds,operations,elapsed_ns,checksum,verify,cleanup");
    for (unsigned width = 0; width < 2; ++width)
        for (unsigned shape = 0; shape < 2; ++shape)
            for (uint64_t op = 0; op < 2; ++op)
                for (unsigned sample = 0; sample < SAMPLES; ++sample)
                    for (unsigned turn = 0; turn < IMPLEMENTATIONS; ++turn) {
                        unsigned peer = (sample + turn) % IMPLEMENTATIONS;
                        if (cohort) peer = IMPLEMENTATIONS - 1 - peer;
                        const Api *api = &apis[width * IMPLEMENTATIONS + peer];
                        uint64_t target = slots[cohort ? 1 - shape : shape];
                        uint64_t count = target / 2;
                        uint64_t rounds = (work + count - 1) / count;
                        uint64_t seed = 101 + sample;
                        Storage storage = {0};
                        api->prepare(storage.bytes, target, count, seed);
                        uint64_t geometry = api->geometry(storage.bytes);
                        require((uint32_t)geometry == count, "timed population");
                        require((geometry >> 32) == expected_capacity(api, target), "timed capacity");
                        /* One complete untimed batch on this SAME owner. */
                        uint64_t warmup = api->batch(storage.bytes, rounds, op);
                        require(warmup == expected_batch(api->wide, count, seed, 0, rounds, op), "warmup batch oracle");
                        require(api->geometry(storage.bytes) == geometry, "warmup geometry");
                        require(api->verify(storage.bytes) == expected_verify(count, seed, rounds), "warmup verify oracle");
                        observed ^= warmup;
                        uint64_t start_generation = rounds;
                        uint64_t start = nanoseconds();
                        uint64_t actual = api->batch(storage.bytes, rounds, op);
                        uint64_t elapsed = nanoseconds() - start;
                        require(actual == expected_batch(api->wide, count, seed, start_generation, rounds, op), "timed batch oracle");
                        require(api->geometry(storage.bytes) == geometry, "timed geometry");
                        uint64_t verify = api->verify(storage.bytes);
                        require(verify == expected_verify(count, seed, start_generation + rounds), "timed verify oracle");
                        uint64_t cleanup = api->finish(storage.bytes);
                        require(cleanup == expected_cleanup(api->wide, count, seed, start_generation + rounds), "timed cleanup oracle");
                        clean_ledger(); observed ^= actual ^ verify ^ cleanup;
                        printf("%s,%s,%s,%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%s,%u,%u,%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 "\n",
                               api->name, api->capacity_kind, api->wide ? "wide256" : "word8",
                               target, count, geometry >> 32, op ? "churn" : "replace",
                               cohort, sample, seed, start_generation, rounds, rounds * count,
                               elapsed, actual, verify, cleanup);
                        fflush(stdout);
                    }
}
#endif
int main(int argc, char **argv) {
    require(argc >= 2, "mode");
    if (strcmp(argv[1], "check") == 0) {
        require(argc == 2, "check args"); check_all();
    } else if (strcmp(argv[1], "negative") == 0) {
        require(argc == 3, "negative args"); negative(argv[2]);
#ifdef ACCOUNT_ONLY
    } else if (strcmp(argv[1], "account") == 0) {
        require(argc == 2, "account args"); account();
#endif
#ifndef ACCOUNT_ONLY
    } else if (strcmp(argv[1], "measure") == 0) {
        require(argc == 4 && (strcmp(argv[2], "0") == 0 || strcmp(argv[2], "1") == 0), "measure args");
        measure((unsigned)(argv[2][0] - '0'), parse_work(argv[3]));
#endif
    } else require(false, "unknown mode");
    return 0;
}

