//! Scratch ordinary HashMap replacement/churn comparator. Retire with the
//! rejected experiment or promote into the maintained map harness if selected.
use std::collections::HashMap;
use std::ffi::c_void;
use std::hash::{BuildHasher, Hasher};

#[cfg(account_only)]
#[path = "../../../../ecosystem-allocator.rs"]
mod ecosystem_allocator;

fn mix(mut value: u64) -> u64 {
    value ^= value >> 30;
    value = value.wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value ^= value >> 27;
    value = value.wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

struct AlignedBuild {
    salt: u64,
    collide: bool,
}

struct AlignedHasher {
    salt: u64,
    collide: bool,
    hash: u64,
}

impl BuildHasher for AlignedBuild {
    type Hasher = AlignedHasher;

    fn build_hasher(&self) -> Self::Hasher {
        AlignedHasher {
            salt: self.salt,
            collide: self.collide,
            hash: 0,
        }
    }
}

impl Hasher for AlignedHasher {
    fn finish(&self) -> u64 {
        self.hash
    }

    fn write_u64(&mut self, value: u64) {
        self.hash = if self.collide {
            0
        } else {
            mix(value ^ self.salt)
        };
    }

    fn write(&mut self, bytes: &[u8]) {
        let word: [u8; 8] = bytes.try_into().expect("the aligned key is one u64");
        self.write_u64(u64::from_ne_bytes(word));
    }
}

trait Payload {
    fn make(seed: u64) -> Self;
    fn identity(&self) -> u64;
    fn content(self, key: u64) -> u64;
}

impl Payload for u64 {
    fn make(seed: u64) -> Self {
        seed
    }

    fn identity(&self) -> u64 {
        *self
    }

    fn content(self, key: u64) -> u64 {
        key.wrapping_mul(131).wrapping_add(self)
    }
}

struct Record {
    words: [u64; 32],
}

impl Payload for Record {
    fn make(seed: u64) -> Self {
        Self {
            words: std::array::from_fn(|index| seed.wrapping_add(index as u64)),
        }
    }

    fn identity(&self) -> u64 {
        self.words[0]
    }

    fn content(self, mut key: u64) -> u64 {
        for word in self.words {
            key = key.wrapping_mul(131).wrapping_add(word);
        }
        key
    }
}

struct Digest {
    ordered: u64,
    sum: u64,
    parity: u64,
    count: u64,
}

impl Digest {
    fn new(seed: u64) -> Self {
        Self {
            ordered: seed,
            sum: 0,
            parity: 0,
            count: 0,
        }
    }

    fn ordered(&mut self, value: u64) {
        self.ordered = self.ordered.wrapping_mul(131).wrapping_add(value);
    }

    fn consume(&mut self, value: u64) {
        self.sum = self.sum.wrapping_add(value);
        self.parity ^= mix(value);
        self.count = self.count.wrapping_add(1);
    }

    fn finish(self) -> u64 {
        mix(self.ordered)
            ^ mix(self.sum)
            ^ self.parity
            ^ self.count.wrapping_mul(0x9e37_79b9_7f4a_7c15)
    }
}

fn key_at(index: u64) -> u64 {
    index.wrapping_mul(2).wrapping_add(1)
}

struct MutationState<V> {
    map: HashMap<u64, V, AlignedBuild>,
    count: u64,
    seed: u64,
    generation: u64,
}

unsafe fn mutation_prepare<V: Payload>(storage: *mut c_void, slots: u64, count: u64, seed: u64) {
    assert!(std::mem::size_of::<MutationState<V>>() <= 128);
    assert!(std::mem::align_of::<MutationState<V>>() <= 16);
    assert!(!storage.is_null() && (storage as usize) % 16 == 0);
    assert!(count <= slots && slots <= 8192);
    let mut map = HashMap::with_capacity_and_hasher(
        usize::try_from(slots / 2).expect("mutation capacity fits usize"),
        AlignedBuild {
            salt: seed ^ 0x9e37_79b9_7f4a_7c15,
            collide: false,
        },
    );
    assert!(count <= map.capacity() as u64);
    for index in 0..count {
        map.insert(key_at(index), V::make(seed.wrapping_add(index)));
    }
    // Fresh caller-owned storage holds the native descriptor, without a Box.
    unsafe {
        storage.cast::<MutationState<V>>().write(MutationState {
