}

unsafe fn mutation_batch<V: Payload>(storage: *mut c_void, rounds: u64, operation: u64) -> u64 {
    let state = unsafe { &mut *storage.cast::<MutationState<V>>() };
    let mut digest = Digest::new(state.seed);
    for _ in 0..rounds {
        let next_generation = state.generation.wrapping_add(1);
        let base = state
            .seed
            .wrapping_add(next_generation.wrapping_mul(state.count));
        for index in 0..state.count {
            let key = key_at(index);
            if operation != 0 {
                let removed = state.map.remove_entry(&key);
                digest.ordered(u64::from(removed.is_some()));
                if let Some((old_key, value)) = removed {
                    digest.ordered(value.content(old_key));
                }
            }
            // Payload construction belongs to the ordinary timed insert call.
            let old = state.map.insert(key, V::make(base.wrapping_add(index)));
            digest.ordered(u64::from(old.is_some()));
            if let Some(value) = old {
                // Equal integer keys have identical content in the WF pair.
                digest.ordered(value.content(key));
            }
        }
        state.generation = next_generation;
    }
    digest.finish()
}

unsafe fn mutation_geometry<V>(storage: *const c_void) -> u64 {
    let state = unsafe { &*storage.cast::<MutationState<V>>() };
    // Report Rust's usable capacity, not an invented physical slot count.
    let usable = u32::try_from(state.map.capacity()).expect("mutation capacity fits geometry");
    let length = u32::try_from(state.map.len()).expect("mutation length fits geometry");
    (u64::from(usable) << 32) | u64::from(length)
}

unsafe fn mutation_verify<V: Payload>(storage: *const c_void) -> u64 {
    let state = unsafe { &*storage.cast::<MutationState<V>>() };
    let mut digest = Digest::new(state.seed);
    for index in 0..state.count {
        let key = key_at(index);
        let found = state.map.get(&key);
        digest.ordered(u64::from(found.is_some()));
        if let Some(value) = found {
            digest.ordered(value.identity());
        }
        let missing = state.map.get(&key.wrapping_add(1));
        digest.ordered(u64::from(missing.is_some()));
        if let Some(value) = missing {
            digest.ordered(value.identity());
        }
    }
    digest.finish()
}

unsafe fn mutation_finish<V: Payload>(storage: *mut c_void) -> u64 {
    // Consume once; caller storage is uninitialized again after this call.
    let MutationState { map, seed, .. } = unsafe { storage.cast::<MutationState<V>>().read() };
    let mut digest = Digest::new(seed);
    for (key, value) in map {
        digest.consume(value.content(key));
    }
    digest.finish()
}

macro_rules! mutation_exports {
    ($value:ty, $prepare:ident, $batch:ident, $geometry:ident, $verify:ident, $finish:ident) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $prepare(storage: *mut c_void, slots: u64, count: u64, seed: u64) {
            unsafe { mutation_prepare::<$value>(storage, slots, count, seed) }
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $batch(storage: *mut c_void, rounds: u64, operation: u64) -> u64 {
            unsafe { mutation_batch::<$value>(storage, rounds, operation) }
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $geometry(storage: *const c_void) -> u64 {
            unsafe { mutation_geometry::<$value>(storage) }
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $verify(storage: *const c_void) -> u64 {
            unsafe { mutation_verify::<$value>(storage) }
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $finish(storage: *mut c_void) -> u64 {
            unsafe { mutation_finish::<$value>(storage) }
        }
    };
}

