      let key = doubled +wrap first_key;
      let found = chain_lookup::<MapCostLibraryKey, T, MapCostDigest, u64, fn MapCostElement::observe>(map: &owner^.map, key: &key, key_env: &owner^.env, visit_env: &digest);
