fn chain_lookup_finish<interface MapCostElement<T>>(owner: ChainLookupOwner<T>) -> result: u64 pure {
  let ChainLookupOwner(map: map, env: env, seed: seed) = move owner;
  let ChainMap(heads: heads, entries: entries) = move map;
  let digest = MapCostDigest(ordered: seed, sum: 0_u64, parity: 0_u64, count: 0_u64);
  loop @entries {
    if entries.inner.len == 0_u64 {
      break @entries;
    }
    let node = take_back(window: &entries.inner);
    let ChainEntry(key: saved_key, value: saved_value, next: next) = move node;
    MapCostElement::consume(env: &digest, key: saved_key, value: move saved_value);
  }
  free_empty(window: move entries);
  return map_cost_finish(digest: digest);
}

