fn full_chain_find<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, env: &E) -> result: Result<u64, unit> reads(map), reads(key), reads(env) contract {
  ensures when Ok(value: index): index < map^.entries.inner.len;
} {
  let hash = HashMapKey::hash(env: env, key: key);
  let capacity = map^.heads.inner.len;
  if capacity == 0_u64 {
    return Err<u64, unit>(error: unit);
  }
  let bucket = hash % capacity;
  let index = map^.heads.inner[bucket];
  let count = map^.entries.inner.len;
  for (step in 0_u64..count) {
    if index < count {
      let node = &map^.entries.inner[index];
      let equal = HashMapKey::equal(env: env, left: &node^.key, right: key);
      if equal {
        return Ok<u64, unit>(value: index);
      }
      set index = node^.next;
    } else {
      return Err<u64, unit>(error: unit);
    }
  }
  return Err<u64, unit>(error: unit);
}

fn full_chain_lookup<interface HashMapKey<K, E>, V, F, R, fn observe(env: &F, key: &K, value: &V) -> result: R reads(key), reads(value), writes(env), const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, key_env: &E, visit_env: &F) -> result: Result<R, unit> reads(map), reads(key), reads(key_env), writes(visit_env) {
  let found = full_chain_find::<HashMapKey<K, E>, V, ceiling>(map: map, key: key, env: key_env);
  match found {
    Ok(value: index) => {
      let node = &map^.entries.inner[index];
      let observed = observe(env: visit_env, key: &node^.key, value: &node^.value);
      return Ok<R, unit>(value: move observed);
    }
    Err(error: missing) => {
      return Err<R, unit>(error: unit);
    }
  }
}

fn full_chain_edit<interface HashMapKey<K, E>, V, F, R, fn update(env: &F, key: &K, value: &V) -> result: R reads(key), writes(env), writes(value), const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, key_env: &E, edit_env: &F) -> result: Result<R, unit> reads(key), reads(key_env), writes(map), writes(edit_env) contract {
