fn full_chain_try_put<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: K, value: V, env: &E) -> result: HashMapPut<K, V> reads(env), writes(map) contract {
  ensures map^.heads.inner.len == entry(map)^.heads.inner.len;
  ensures map^.entries.inner.cap == entry(map)^.entries.inner.cap;
} {
  let hash = HashMapKey::hash(env: env, key: &key);
  let capacity = map^.heads.inner.len;
  if capacity > 0_u64 {
    let bucket = hash % capacity;
    let first = map^.heads.inner[bucket];
    let index = first;
    let count = map^.entries.inner.len;
    for @find (step in 0_u64..count) {
      if index < count {
        let node = &map^.entries.inner[index];
        let equal = HashMapKey::equal(env: env, left: &node^.key, right: &key);
        if equal {
          swap(first: &node^.key, second: &key);
          swap(first: &node^.value, second: &value);
          let previous = HashMapPair<K, V>(key: move key, value: move value);
          let reason = HashMapReturnReason::HashMapReplaced();
          return HashMapPut<K, V>::HashMapReturned(reason: reason, pair: move previous);
        }
        set index = node^.next;
      } else {
        break @find;
      }
    }
    if count < capacity {
      if count < ceiling {
        if count < map^.entries.inner.cap {
          let node = FullChainEntry<K, V>(key: move key, value: move value, next: first);
          place_back(window: &map^.entries.inner, value: move node);
          set map^.heads.inner[bucket] = count;
          return HashMapPut<K, V>::HashMapInserted();
        }
      }
    }
  }
  let offered = HashMapPair<K, V>(key: move key, value: move value);
  let reason = HashMapReturnReason::HashMapFull();
  return HashMapPut<K, V>::HashMapReturned(reason: reason, pair: move offered);
}

fn full_chain_relink<K, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, old: u64, replacement: u64) -> result: unit writes(map) contract {
  ensures map^.heads.inner.len == entry(map)^.heads.inner.len;
  ensures map^.entries.inner.len == entry(map)^.entries.inner.len;
  ensures map^.entries.inner.cap == entry(map)^.entries.inner.cap;
} {
  let buckets = map^.heads.inner.len;
  for (index in 0_u64..buckets) {
    if map^.heads.inner[index] == old {
      set map^.heads.inner[index] = replacement;
    }
  }
  let count = map^.entries.inner.len;
  for (index in 0_u64..count) {
    if map^.entries.inner[index].next == old {
      set map^.entries.inner[index].next = replacement;
    }
  }
  return unit;
}

fn full_chain_remove<interface HashMapKey<K, E>, V, const ceiling: u64>(map: &FullChainMap<K, V, ceiling>, key: &K, env: &E) -> result: Option<HashMapPair<K, V>> reads(key), reads(env), writes(map) {
  let count = map^.entries.inner.len;
  if count == 0_u64 {
    return None<HashMapPair<K, V>>();
  }
  let hash = HashMapKey::hash(env: env, key: key);
  let buckets = map^.heads.inner.len;
  if buckets == 0_u64 {
    return None<HashMapPair<K, V>>();
  }
  let bucket = hash % buckets;
  let index = map^.heads.inner[bucket];
  let predecessor = count;
  for (step in 0_u64..count) {
    if index < count {
      let equal = HashMapKey::equal(env: env, left: &map^.entries.inner[index].key, right: key);
      if equal {
